import math

def is_power_of_5(num):
    if num <= 0:
        return False
    if num == 1: # 5^0 = 1, but since n>=3, 2^n-3 >= 2^3-3 = 5, so k must be >= 1
        return False 

    # Check if num is divisible by 5 repeatedly
    while num > 1 and num % 5 == 0:
        num //= 5
    return num == 1

solutions = []
for n in range(3, 16):
    X = 2**n - 3
    if is_power_of_5(X):
        # Find k such that 5^k = X
        k = round(math.log(X, 5))
        if 5**k == X:
            solutions.append((n, k))

print("Solutions (n, k) found:")
for n, k in solutions:
    print(f"n={n}, k={k}")

print("All solutions:", solutions)

def check_solution(n):
    if n < 3:
        return False
    value = 2**n - 3
    if value <= 0:
        return False

    k = 0
    temp = value
    while temp > 0 and temp % 5 == 0:
        temp //= 5
        k += 1

    if temp == 1:
        return (True, k)
    else:
        return (False, None)

# Test small n values
solutions = []
for n in range(3, 30):
    success, k = check_solution(n)
    if success:
        solutions.append((n, k))

print("Solutions (n, k) found up to n=29:")
print(solutions)

